scan_table_check.script:
(function(engine, current) {
    var property = 'instance_scan.peer_review.names.script_include';
    var pattern = String(gs.getProperty(property, '') || '');
    if (!pattern) {
        return;
    }
    var context = new global.EcsContext(current);
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-SI-001',
        title: 'Script Include name does not follow the naming convention',
        recommendation: 'Rename the Script Include (and every reference to it) to match the convention in the ' +
            'system property ' + property + '.',
        current: current
    });
    var regex;
    try {
        regex = new RegExp(pattern);
    } catch (e) {
        report.addRecord('The naming convention in ' + property + ' is not a valid regular expression: ' + pattern);
        engine.finding.setCurrentSource(current);
        report.flush();
        return;
    }
    var name = context.value('name');
    if (regex.test(name)) {
        return;
    }
    report.addRecord('Script Include "' + name + '" does not match the naming convention ' + pattern + ' (' + property + ').');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
